#!/usr/bin/env python3
"""
check-voice-populated.py

Deterministic check for whether AUTHOR_VOICE.md is a real, usable voice profile
or an unpopulated stub. See src/skills/voice/references/stub-definition.md for
the full rationale — this script is the enforceable implementation of that
definition, not a separate heuristic.

A file is a STUB (exit 1) if either:
  1. It is missing, OR
  2. The title/`> Updated` line still contain the untouched template placeholders
     (`<writer name>`, `<YYYY-MM-DD>`, `<plugin>`), OR
  3. All four required sections are empty (only `_Empty.` / blank content), OR
  4. Total word count across all section bodies is below the minimum-content floor
     (default 20 words), even if some section is technically non-empty.

A file is POPULATED (exit 0) only if none of the above hold.

Usage:
    python3 scripts/check-voice-populated.py [path] [--json] [--min-words N]

    path        Defaults to AUTHOR_VOICE.md in the current directory.
    --json      Emit a machine-readable {"populated": bool, "reasons": [...], ...} payload.
    --min-words Override the minimum total word-count floor (default: 20).

Exit codes:
    0  populated (real, usable voice profile)
    1  stub (missing, untouched template, or below the content floor)
    2  usage error (bad path argument, unreadable/non-UTF-8 file)

Dependency-free (Python 3 stdlib only).
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

REQUIRED_SECTIONS = [
    "Core voice (cross-project)",
    "Terminology",
    "Academic-specific",
    "Non-fiction-book-specific",
]

DEFAULT_MIN_WORDS = 20

TITLE_PLACEHOLDER = "<writer name>"
UPDATED_PLACEHOLDER_MARKERS = ("<YYYY-MM-DD>", "<plugin>")

# Matches the bare `_Empty._` placeholder AND the descriptive variant used in the
# freshly-scaffolded template (`_Empty. Populated by Stage 1 miner and Stage 2 interview._`) --
# any italic-wrapped line that starts with "Empty" is a placeholder, not real content.
EMPTY_MARKER_RE = re.compile(r"^_Empty\b.*_$", re.IGNORECASE)
HEADING_RE = re.compile(r"^##\s+(.+?)\s*$")
COMMENT_TRAILER_RE = re.compile(r"^<!--.*-->$")


def split_sections(text: str) -> dict[str, str]:
    """Return {section_name: body_text} for each `## <name>` heading in text."""
    lines = text.splitlines()
    sections: dict[str, list[str]] = {}
    current: str | None = None
    for line in lines:
        m = HEADING_RE.match(line)
        if m:
            current = m.group(1).strip()
            sections.setdefault(current, [])
            continue
        if current is not None:
            sections[current].append(line)
    return {name: "\n".join(body) for name, body in sections.items()}


def section_word_count(body: str) -> int:
    """Word count of a section body, excluding blank lines, the `_Empty._`
    placeholder, and HTML comment trailers."""
    words = 0
    for line in body.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if EMPTY_MARKER_RE.match(stripped):
            continue
        if COMMENT_TRAILER_RE.match(stripped):
            continue
        words += len(stripped.split())
    return words


def check(text: str, min_words: int = DEFAULT_MIN_WORDS) -> dict:
    reasons: list[str] = []

    title_line = next((l for l in text.splitlines() if l.startswith("# ")), "")
    updated_line = next(
        (l for l in text.splitlines() if l.strip().startswith("> Updated")), ""
    )

    placeholder_untouched = TITLE_PLACEHOLDER in title_line or any(
        marker in updated_line for marker in UPDATED_PLACEHOLDER_MARKERS
    )
    if placeholder_untouched:
        reasons.append("placeholder_untouched")

    sections = split_sections(text)
    section_words = {
        name: section_word_count(sections.get(name, "")) for name in REQUIRED_SECTIONS
    }
    populated_sections = sum(1 for w in section_words.values() if w > 0)
    total_words = sum(section_words.values())

    if populated_sections == 0:
        reasons.append("all_sections_empty")
    elif total_words < min_words:
        reasons.append("below_minimum_content")

    populated = len(reasons) == 0
    return {
        "populated": populated,
        "reasons": reasons,
        "populatedSections": populated_sections,
        "totalWords": total_words,
    }


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("path", nargs="?", default="AUTHOR_VOICE.md")
    parser.add_argument(
        "--json", action="store_true", help="Emit machine-readable JSON payload."
    )
    parser.add_argument(
        "--min-words", type=int, default=DEFAULT_MIN_WORDS, dest="min_words"
    )
    args = parser.parse_args(argv)

    path = Path(args.path)

    if not path.is_file():
        result = {
            "populated": False,
            "path": str(path),
            "reasons": ["missing"],
            "populatedSections": 0,
            "totalWords": 0,
        }
        if args.json:
            print(json.dumps(result))
        else:
            print(f"STUB: {path} does not exist")
        return 1

    try:
        text = path.read_text(encoding="utf-8", errors="strict")
    except UnicodeDecodeError as e:
        if args.json:
            print(
                json.dumps(
                    {
                        "populated": None,
                        "path": str(path),
                        "error": f"not valid UTF-8: {e}",
                    }
                )
            )
        else:
            print(f"ERROR: {path} is not valid UTF-8: {e}", file=sys.stderr)
        return 2

    result = check(text, min_words=args.min_words)
    result["path"] = str(path)

    if args.json:
        print(json.dumps(result))
    else:
        if result["populated"]:
            print(
                f"POPULATED: {path} ({result['populatedSections']}/4 sections, "
                f"{result['totalWords']} words)"
            )
        else:
            print(f"STUB: {path} — reasons: {', '.join(result['reasons'])}")

    return 0 if result["populated"] else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
